export const title = "How to Set Up an Entryway Drop Zone When You Have No Hallway";
export const metaTitle = "How to Set Up an Entryway Drop Zone When You";
export const metaDescription = "Build an entryway drop zone without a hallway while preserving door movement and keeping everyday belongings accessible.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-17";
